package forth

import (
	"errors"
	"strconv"
	"strings"
)

// token is either a number (word == "") or a word (word != "").
type token struct {
	num  int
	word string
}

type forth struct {
	stack []int
	dict  map[string][]token
}

var builtinWords = map[string]bool{
	"+": true, "-": true, "*": true, "/": true,
	"dup": true, "drop": true, "swap": true, "over": true,
}

func Forth(input []string) ([]int, error) {
	f := &forth{
		stack: []int{},
		dict:  make(map[string][]token),
	}
	for _, line := range input {
		if err := f.evalLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

func (f *forth) evalLine(line string) error {
	tokens := strings.Fields(line)
	if len(tokens) == 0 {
		return nil
	}
	if tokens[0] == ":" {
		return f.define(tokens[1:])
	}
	return f.exec(tokens)
}

func (f *forth) define(tokens []string) error {
	if len(tokens) < 2 {
		return errors.New("malformed definition")
	}
	name := strings.ToLower(tokens[0])
	if _, err := strconv.Atoi(name); err == nil {
		return errors.New("cannot redefine a number")
	}
	body := make([]token, 0, len(tokens)-1)
	for _, tok := range tokens[1:] {
		if tok == ";" {
			f.dict[name] = body
			return nil
		}
		body = append(body, f.resolve(tok))
	}
	return errors.New("missing ; in definition")
}

// resolve converts a definition token into its current meaning:
// numbers are kept as-is, user-defined words are expanded to their
// (already-expanded) bodies, and everything else is kept as a word
// to be resolved at execution time.
func (f *forth) resolve(s string) []token {
	if n, err := strconv.Atoi(s); err == nil {
		return []token{{num: n}}
	}
	name := strings.ToLower(s)
	if body, ok := f.dict[name]; ok {
		return body
	}
	return []token{{word: name}}
}

func (f *forth) exec(tokens []string) error {
	for _, s := range tokens {
		if n, err := strconv.Atoi(s); err == nil {
			f.stack = append(f.stack, n)
			continue
		}
		name := strings.ToLower(s)
		if body, ok := f.dict[name]; ok {
			if err := f.execTokens(body); err != nil {
				return err
			}
			continue
		}
		if err := f.execBuiltin(name); err != nil {
			return err
		}
	}
	return nil
}

func (f *forth) execTokens(body []token) error {
	for _, tok := range body {
		if tok.word == "" {
			f.stack = append(f.stack, tok.num)
			continue
		}
		if body, ok := f.dict[tok.word]; ok {
			if err := f.execTokens(body); err != nil {
				return err
			}
			continue
		}
		if err := f.execBuiltin(tok.word); err != nil {
			return err
		}
	}
	return nil
}
